/// One registered subcommand: name, owning card, help text and entry point.
pub struct Subcommand {
    /// Name typed after `cargo xtask`.
    pub name: &'static str,
    /// Owning card in `docs/13-agent-wave-program.md`.
    pub card: &'static str,
    /// One-line summary for `cargo xtask help`.
    pub summary: &'static str,
    /// Whether the owning card has landed (drives the help status label).
    pub implemented: bool,
    /// Entry point; receives the args after the subcommand name.
    pub run: fn(&[String]) -> Result<ExitCode, XtaskError>,
}

